char *X509_TRUST_get0_name(const X509_TRUST *xp);
/**
 * @brief Return the trust purpose identifier of an X509_TRUST table entry.
 * @param xp Trust entry to query.
 * @return Trust id such as X509_TRUST_SSL_CLIENT or X509_TRUST_SSL_SERVER.
 */
int X509_TRUST_get_trust(const X509_TRUST *xp);

/**
 * @brief Report whether a certificate has auxiliary trust information attached.
 * @param x Certificate to query.
 * @return Non-zero if trust aux data is present, or 0 otherwise.
 */
int X509_trusted(const X509 *x);
/**
 * @brief Append an OID to a certificate's auxiliary trust list.
 * @param x Certificate whose trust objects are extended (creates aux data if needed).
 * @param obj Purpose/OID that should cause the certificate to be trusted when matched.
 * @return 1 on success, or 0 on failure.
 */
int X509_add1_trust_object(X509 *x, const ASN1_OBJECT *obj);
/**
 * @brief Append an OID to a certificate's auxiliary reject list.
 * @param x Certificate whose reject objects are extended (creates aux data if needed).
 * @param obj Purpose/OID that should cause the certificate to be rejected when matched.
 * @return 1 on success, or 0 on failure.
 */
int X509_add1_reject_object(X509 *x, const ASN1_OBJECT *obj);
/**
 * @brief Clear all explicit trust object identifiers previously set on a certificate.
 * @param x Certificate whose trust OID stack is freed and reset.
 */
void X509_trust_clear(X509 *x);
/**
 * @brief Clear all auxiliary reject-object OIDs attached to a certificate.
 * @param x Certificate whose reject OID stack is freed and reset.
 */
void X509_reject_clear(X509 *x);
/**
 * @brief Return the stack of explicit trust object identifiers attached to a certificate.
 * @param x Certificate whose auxiliary trust OIDs are queried.
 * @return Internal stack of ASN1_OBJECT values, or NULL if none; do not free the result.
 */
STACK_OF(ASN1_OBJECT) *X509_get0_trust_objects(X509 *x);
/**
 * @brief Return the stack of reject OIDs from a certificate's auxiliary data.
 * @param x Certificate to query.
 * @return Internal STACK_OF(ASN1_OBJECT) (do not free), or NULL if none.
 */
STACK_OF(ASN1_OBJECT) *X509_get0_reject_objects(X509 *x);

/**
 * @brief Install a process-wide default trust-checking callback.
 * @param trust Callback of the form int trust(int id, X509 *x, int flags), or NULL to restore the built-in default.
 * @return Previous default trust callback.
 */
int (*X509_TRUST_set_default(int (*trust)(int, X509 *, int)))(int, X509 *,
    int);
/**
 * @brief Evaluate whether a certificate is trusted for a given trust id.
 * @param x Certificate to check (including any auxiliary trust/reject OIDs).
 * @param id Trust purpose id (X509_TRUST_*); X509_TRUST_DEFAULT uses anyExtendedKeyUsage compatibility.
 * @param flags X509_TRUST_* flag bits controlling compatibility checks.
 * @return X509_TRUST_TRUSTED, X509_TRUST_REJECTED, or X509_TRUST_UNTRUSTED.
 */
int X509_check_trust(X509 *x, int id, int flags);

/**
 * @brief Discover and validate a certificate chain based on parameters in @p ctx.
 * @param ctx Initialized verification context (see X509_STORE_CTX_new() and X509_STORE_CTX_init()).
 * @return 1 if a complete chain can be built and validated, 0 on failure, or a negative value on exceptional error.
 *
 * Applications must treat any return value <= 0 as an error. On failure, inspect @p ctx
 * with X509_STORE_CTX_get_error().
 */
int X509_verify_cert(X509_STORE_CTX *ctx);
/**
 * @brief Verify the certificate chain prepared in an X509_STORE_CTX.
 * @param ctx Initialized verification context (see X509_STORE_CTX_init()).
 * @return 1 if verification succeeded, 0 if it failed, or a negative value on exceptional error.
 */
int X509_STORE_CTX_verify(X509_STORE_CTX *ctx);
/**
 * @brief Build a certificate chain for @p target using untrusted @p certs and trusted @p store.
 * @param target End-entity certificate to chain up from.
 * @param certs Optional untrusted intermediate certificates, or NULL.
 * @param store Trusted certificate store used for trust anchors, or NULL.
 * @param with_self_signed Non-zero to include a self-signed trust anchor in the result.
 * @param libctx Library context for algorithm fetches, or NULL for the default.
 * @param propq Property query string, or NULL.
 * @return Newly allocated chain stack (caller frees with sk_X509_pop_free), or NULL on failure.
 */
STACK_OF(X509) *X509_build_chain(X509 *target, STACK_OF(X509) *certs,
    X509_STORE *store, int with_self_signed,
    OSSL_LIB_CTX *libctx, const char *propq);

/**
 * @brief Set the maximum untrusted chain depth for verifications using @p store.
 * @param store Certificate store whose default verify parameters are updated.
 * @param depth Maximum number of untrusted intermediate CA certificates.
 * @return 1 on success, or 0 on failure.
 */
int X509_STORE_set_depth(X509_STORE *store, int depth);

/**
 * @brief Verify-result callback invoked for each certificate during chain verification.
 * @param ok Current verification result (1 if OK so far, 0 if an error was recorded).
 * @param ctx Store context describing the certificate under examination and any error.
 * @return Non-zero to continue/accept, or 0 to fail verification.
 */
typedef int (*X509_STORE_CTX_verify_cb)(int ok, X509_STORE_CTX *ctx);
/**
 * @brief Default verify callback that prints diagnosis details when verification fails.
 * @param ok Current verification status (1 success, 0 failure).
 * @param ctx Store context describing the failure/success.
 * @return The (possibly unchanged) @p ok value after logging.
 */
int X509_STORE_CTX_print_verify_cb(int ok, X509_STORE_CTX *ctx);
/**
 * @brief Callback that verifies a certificate chain in an X509_STORE_CTX.
 * @param ctx Store context whose chain and trust settings are used.
 * @return 1 if verification succeeds, or 0 on failure.
 */
typedef int (*X509_STORE_CTX_verify_fn)(X509_STORE_CTX *ctx);
/**
 * @brief Callback that finds an issuer certificate for @p x.
 * @param issuer Receives the issuer certificate (typically with an incremented reference).
 * @param ctx Store context providing lookup state.
 * @param x Certificate whose issuer is sought.
 * @return 1 on success, or 0 on failure.
 */
typedef int (*X509_STORE_CTX_get_issuer_fn)(X509 **issuer,
    X509_STORE_CTX *ctx, X509 *x);
/**
 * @brief Callback type that checks whether @p issuer appears to have issued @p x.
 * @param ctx Verification context performing the check.
 * @param x Candidate subject certificate.
 * @param issuer Candidate issuer certificate.
 * @return 1 if @p issuer issued @p x, or 0 otherwise.
 */
typedef int (*X509_STORE_CTX_check_issued_fn)(X509_STORE_CTX *ctx,
    X509 *x, X509 *issuer);
/**
 * @brief Callback that checks revocation status for certificates in a store context.
 * @param ctx Verification context whose current chain should be revocation-checked.
 * @return 1 if revocation checks succeed, or 0 on failure.
 */
typedef int (*X509_STORE_CTX_check_revocation_fn)(X509_STORE_CTX *ctx);
/**
 * @brief Callback type that locates a CRL for certificate @p x.
 * @param ctx Verification context performing the lookup.
 * @param crl On success, set to the found CRL (caller/context manages lifetime per OpenSSL rules).
 * @param x Certificate for which a CRL is needed.
 * @return 1 on success, or 0 on failure.
 */
typedef int (*X509_STORE_CTX_get_crl_fn)(X509_STORE_CTX *ctx,
    X509_CRL **crl, X509 *x);
/**
 * @brief Callback type that verifies the signature/validity of a CRL in context @p ctx.
 * @param ctx Verification context performing the check.
 * @param crl CRL whose authenticity is checked.
 * @return 1 on success, or 0 on failure.
 */
typedef int (*X509_STORE_CTX_check_crl_fn)(X509_STORE_CTX *ctx, X509_CRL *crl);
/**
 * @brief Callback type that checks the revocation status of a certificate against a CRL.
 * @param ctx Verification context performing the check.
 * @param crl CRL to consult.
 * @param x Certificate whose revocation status is checked.
 * @return 1 on success, or 0 on failure.
 */
typedef int (*X509_STORE_CTX_cert_crl_fn)(X509_STORE_CTX *ctx,
    X509_CRL *crl, X509 *x);
/**
 * @brief Callback type that evaluates certificate policies for a verification context.
 * @param ctx Store context whose chain and policy state are examined.
 * @return 1 if policy checking succeeds, or 0 on failure.
 */
typedef int (*X509_STORE_CTX_check_policy_fn)(X509_STORE_CTX *ctx);
/**
 * @brief Callback type that looks up certificates in a store by subject name.
 * @param ctx Verification context whose store is searched.
 * @param nm Subject name to match.
 * @return New stack of matching certificates (caller frees), or NULL if none / on error.
 */
typedef STACK_OF(X509)
    *(*X509_STORE_CTX_lookup_certs_fn)(X509_STORE_CTX *ctx,
        const X509_NAME *nm);
/**
 * @brief Callback type that returns CRLs matching issuer name @p nm.
 * @param ctx Verification context performing the lookup.
 * @param nm CRL issuer name to search for.
 * @return Newly allocated stack of X509_CRL, or NULL on failure; caller frees with sk_X509_CRL_pop_free.
 */
typedef STACK_OF(X509_CRL)
    *(*X509_STORE_CTX_lookup_crls_fn)(const X509_STORE_CTX *ctx,
        const X509_NAME *nm);
/**
 * @brief Callback type invoked to clean up application state associated with a store context.
 * @param ctx Verification context being cleaned up.
 * @return 1 on success, or 0 on failure.
 */
typedef int (*X509_STORE_CTX_cleanup_fn)(X509_STORE_CTX *ctx);

/**
 * @brief Limit how deep an X509_STORE_CTX certificate chain may grow during verification.
 * @param ctx Verification context to update.
 * @param depth Maximum number of untrusted CA certificates allowed above the leaf (same meaning as X509_VERIFY_PARAM_set_depth()).
 */
void X509_STORE_CTX_set_depth(X509_STORE_CTX *ctx, int depth);

#define X509_STORE_CTX_set_app_data(ctx, data) \
    X509_STORE_CTX_set_ex_data(ctx, 0, data)
#define X509_STORE_CTX_get_app_data(ctx) \
    X509_STORE_CTX_get_ex_data(ctx, 0)

#define X509_L_FILE_LOAD 1
#define X509_L_ADD_DIR 2
#define X509_L_ADD_STORE 3
#define X509_L_LOAD_STORE 4

#define X509_LOOKUP_load_file(x, name, type) \
    X509_LOOKUP_ctrl((x), X509_L_FILE_LOAD, (name), (long)(type), NULL)

#define X509_LOOKUP_add_dir(x, name, type) \
    X509_LOOKUP_ctrl((x), X509_L_ADD_DIR, (name), (long)(type), NULL)

#define X509_LOOKUP_add_store(x, name) \
    X509_LOOKUP_ctrl((x), X509_L_ADD_STORE, (name), 0, NULL)

#define X509_LOOKUP_load_store(x, name) \
    X509_LOOKUP_ctrl((x), X509_L_LOAD_STORE, (name), 0, NULL)

#define X509_LOOKUP_load_file_ex(x, name, type, libctx, propq)             \
    X509_LOOKUP_ctrl_ex((x), X509_L_FILE_LOAD, (name), (long)(type), NULL, \
        (libctx), (propq))

#define X509_LOOKUP_load_store_ex(x, name, libctx, propq)        \
    X509_LOOKUP_ctrl_ex((x), X509_L_LOAD_STORE, (name), 0, NULL, \
        (libctx), (propq))

#define X509_LOOKUP_add_store_ex(x, name, libctx, propq)        \
    X509_LOOKUP_ctrl_ex((x), X509_L_ADD_STORE, (name), 0, NULL, \
        (libctx), (propq))

